1	package com.example.starter.fermentation.service;
2	
3	import com.example.starter.fermentation.api.BatchDtos.BatchResponse;
4	import com.example.starter.fermentation.api.BatchDtos.CoolingRequest;
5	import com.example.starter.fermentation.api.BatchDtos.CreateBatchRequest;
6	import com.example.starter.fermentation.api.BatchDtos.DiacetylResponse;
7	import com.example.starter.fermentation.api.BatchDtos.DiacetylTestRequest;
8	import com.example.starter.fermentation.api.BatchDtos.ExtendMaturationRequest;
9	import com.example.starter.fermentation.api.BatchDtos.JudgeRequest;
10	import com.example.starter.fermentation.api.BatchDtos.JudgeResponse;
11	import com.example.starter.fermentation.api.BatchDtos.LateResponse;
12	import com.example.starter.fermentation.api.BatchDtos.ReadingResponse;
13	import com.example.starter.fermentation.api.BatchDtos.StartPhaseRequest;
14	import com.example.starter.fermentation.api.BatchDtos.TemperatureReadingRequest;
15	import com.example.starter.fermentation.api.BatchDtos.TransferRequest;
16	import com.example.starter.fermentation.domain.BatchStatus;
17	import com.example.starter.fermentation.domain.CurvePhase;
18	import com.example.starter.fermentation.domain.DiacetylTest;
19	import com.example.starter.fermentation.domain.FermentationBatch;
20	import com.example.starter.fermentation.domain.TemperatureReading;
21	import com.example.starter.fermentation.error.ApiException;
22	import com.example.starter.fermentation.repository.BatchRepository;
23	import com.example.starter.fermentation.repository.CurveRepository;
24	import com.example.starter.fermentation.repository.ReadingRepository;
25	import com.example.starter.fermentation.service.IdempotencyService.ConcurrentReplayException;
26	import com.example.starter.fermentation.service.IdempotencyService.StoredResponse;
27	import com.fasterxml.jackson.core.JsonProcessingException;
28	import com.fasterxml.jackson.databind.ObjectMapper;
29	import org.springframework.dao.DuplicateKeyException;
30	import org.springframework.stereotype.Service;
31	import org.springframework.transaction.annotation.Transactional;
32	import org.springframework.transaction.interceptor.TransactionAspectSupport;
33	
34	import java.math.BigDecimal;
35	import java.time.Duration;
36	import java.time.LocalDateTime;
37	import java.util.ArrayList;
38	import java.util.Comparator;
39	import java.util.List;
40	import java.util.function.Supplier;
41	
42	/**
43	 * 发酵批次核心服务：状态机流转、主酵分段控温告警、双乙酰判定、
44	 * 降温与曲线版本切换同事务、后熟时长判定、清酒转出终态与迟到数据。
45	 *
46	 * <p>判定口径（均可由落库数据复算）：温度偏差恰 0.5℃ 合格，连续 3 个超差采样点（恰 3 点）告警；
47	 * 双乙酰连续两次不超过 0.10mg/L（恰 0.10 合格）且间隔不少于 12 小时（恰 12 小时合法）方可降温；
48	 * 后熟不少于 7 天（恰 7 天合法），仅允许延长一次（延长后要求 14 天），延长后仍不合格整批复审。
49	 */
50	@Service
51	public class BatchService {
52	
53	    /** 温度允许偏差（℃），恰 0.5 合格。 */
54	    static final BigDecimal TEMP_TOLERANCE = new BigDecimal("0.5");
55	    /** 连续超差告警点数，恰 3 点触发。 */
56	    static final int ALARM_CONSECUTIVE = 3;
57	    /** 双乙酰合格上限（mg/L），恰 0.10 合格。 */
58	    static final BigDecimal DIACETYL_LIMIT = new BigDecimal("0.10");
59	    /** 双乙酰两次采样最小间隔（小时），恰 12 小时合法。 */
60	    static final long DIACETYL_MIN_INTERVAL_HOURS = 12;
61	    /** 后熟最短天数，恰 7 天合法。 */
62	    static final int MATURATION_MIN_DAYS = 7;
63	    /** 延长后熟后要求的总天数。 */
64	    static final int MATURATION_EXTENDED_DAYS = 14;
65	
66	    private final BatchRepository batchRepository;
67	    private final CurveRepository curveRepository;
68	    private final ReadingRepository readingRepository;
69	    private final IdempotencyService idempotencyService;
70	    private final ObjectMapper objectMapper;
71	
72	    public BatchService(BatchRepository batchRepository, CurveRepository curveRepository,
73	                        ReadingRepository readingRepository, IdempotencyService idempotencyService,
74	                        ObjectMapper objectMapper) {
75	        this.batchRepository = batchRepository;
76	        this.curveRepository = curveRepository;
77	        this.readingRepository = readingRepository;
78	        this.idempotencyService = idempotencyService;
79	        this.objectMapper = objectMapper;
80	    }
81	
82	    /**
83	     * 创建批次（满罐）。同一发酵罐同时刻仅允许一个进行中批次，并发由唯一约束兜底。
84	     */
85	    @Transactional
86	    public StoredResponse createBatch(CreateBatchRequest req) {
87	        String endpoint = "POST /api/batches";
88	        String fingerprint = idempotencyService.fingerprint(endpoint, req.requestId(),
89	                req.batchNo(), req.tankCode(), req.curveCode(), req.filledAt().toString());
90	        return idempotent(req.requestId(), endpoint, fingerprint, () -> {
91	            long tankId = batchRepository.findTankIdByCode(req.tankCode())
92	                    .orElseThrow(() -> ApiException.notFound("发酵罐不存在: " + req.tankCode()));
93	            int curveVersion = curveRepository.findActiveVersion(req.curveCode())
94	                    .orElseThrow(() -> ApiException.unprocessable("工艺曲线无生效版本: " + req.curveCode()));
95	            long id;
96	            try {
97	                id = batchRepository.insert(req.batchNo(), tankId, req.curveCode(), curveVersion,
98	                        req.filledAt(), req.tankCode());
99	            } catch (DuplicateKeyException e) {
100	                throw translateInsertConflict(e, req);
101	            }
102	            FermentationBatch batch = mustFind(id);
103	            return new StoredResponse(201, toJson(toResponse(batch)));
104	        });
105	    }
106	
107	    /**
108	     * 开始主酵：FILLED → MAIN_FERMENT。
109	     */
110	    @Transactional
111	    public StoredResponse startMainFerment(long batchId, StartPhaseRequest req) {
112	        String endpoint = "POST /api/batches/" + batchId + "/main-ferment/start";
113	        String fingerprint = idempotencyService.fingerprint(endpoint, req.requestId(),
114	                req.startedAt().toString());
115	        return idempotent(req.requestId(), endpoint, fingerprint, () -> {
116	            FermentationBatch batch = mustFind(batchId);
117	            requireStatus(batch, BatchStatus.FILLED, "仅满罐批次可开始主酵");
118	            batchRepository.startMainFerment(batchId, req.startedAt());
119	            return new StoredResponse(200, toJson(toResponse(mustFind(batchId))));
120	        });
121	    }
122	
123	    /**
124	     * 上报温度采样。按采样时刻所在分段复算设定值；偏差恰 0.5℃ 合格；
125	     * 连续 3 个超差点（恰 3 点）触发告警。批次已转出时仅记录迟到事件。
126	     */
127	    @Transactional
128	    public StoredResponse addTemperatureReading(long batchId, TemperatureReadingRequest req) {
129	        String endpoint = "POST /api/batches/" + batchId + "/temperature-readings";
130	        String fingerprint = idempotencyService.fingerprint(endpoint, req.requestId(),
131	                req.sampledAt().toString(), req.temperature().toPlainString());
132	        return idempotent(req.requestId(), endpoint, fingerprint, () -> {
133	            FermentationBatch batch = mustFind(batchId);
134	            if (batch.status() == BatchStatus.TRANSFERRED) {
135	                readingRepository.insertLateEvent(batchId, "TEMPERATURE_READING",
136	                        "sampledAt=" + req.sampledAt() + ",temperature=" + req.temperature().toPlainString(),
137	                        req.sampledAt());
138	                return new StoredResponse(202,
139	                        toJson(new LateResponse(true, "TEMPERATURE_READING", batchId)));
140	            }
141	            CurvePhase phase = switch (batch.status()) {
142	                case MAIN_FERMENT -> CurvePhase.MAIN_FERMENT;
143	                case COOLING -> CurvePhase.COOLING;
144	                case MATURATION -> CurvePhase.MATURATION;
145	                default -> throw ApiException.unprocessable(
146	                        "批次状态 " + batch.status() + " 不接受温度采样");
147	            };
148	            LocalDateTime phaseStart = phaseStart(batch, phase);
149	            if (req.sampledAt().isBefore(phaseStart)) {
150	                throw ApiException.unprocessable("采样时间早于当前阶段开始时间");
151	            }
152	            long elapsedHours = Duration.between(phaseStart, req.sampledAt()).toHours();
153	            BigDecimal setpoint = curveRepository.setpointAt(
154	                    batch.curveCode(), batch.curveVersion(), phase, elapsedHours);
155	            BigDecimal deviation = req.temperature().subtract(setpoint).abs();
156	            boolean outOfTolerance = deviation.compareTo(TEMP_TOLERANCE) > 0;
157	
158	            List<TemperatureReading> history = new ArrayList<>(
159	                    readingRepository.findReadings(batchId, phase));
160	            TemperatureReading pending = new TemperatureReading(0L, batchId, batch.curveVersion(),
161	                    phase, req.sampledAt(), req.temperature(), setpoint, deviation,
162	                    outOfTolerance, 0, false, false);
163	            history.add(pending);
164	            history.sort(Comparator.comparing(TemperatureReading::sampledAt)
165	                    .thenComparing(TemperatureReading::id));
166	            int position = history.indexOf(pending);
167	            int consecutiveOut = 0;
168	            for (int i = position; i >= 0 && history.get(i).outOfTolerance(); i--) {
169	                consecutiveOut++;
170	            }
171	            boolean alarm = consecutiveOut >= ALARM_CONSECUTIVE;
172	
173	            long id = readingRepository.insertReading(batchId, batch.curveVersion(), phase,
174	                    req.sampledAt(), req.temperature(), setpoint, deviation,
175	                    outOfTolerance, consecutiveOut, alarm, false);
176	            ReadingResponse response = new ReadingResponse(id, batchId, phase, batch.curveVersion(),
177	                    req.sampledAt(), req.temperature(), setpoint, deviation,
178	                    outOfTolerance, consecutiveOut, alarm, false);
179	            return new StoredResponse(201, toJson(response));
180	        });
181	    }
182	
183	    /**
184	     * 上报双乙酰检测。批次已转出时仅记录迟到事件。
185	     */
186	    @Transactional
187	    public StoredResponse addDiacetylTest(long batchId, DiacetylTestRequest req) {
188	        String endpoint = "POST /api/batches/" + batchId + "/diacetyl-tests";
189	        String fingerprint = idempotencyService.fingerprint(endpoint, req.requestId(),
190	                req.testedAt().toString(), req.valueMgPerLiter().toPlainString());
191	        return idempotent(req.requestId(), endpoint, fingerprint, () -> {
192	            FermentationBatch batch = mustFind(batchId);
193	            if (batch.status() == BatchStatus.TRANSFERRED) {
194	                readingRepository.insertLateEvent(batchId, "DIACETYL_TEST",
195	                        "testedAt=" + req.testedAt() + ",value=" + req.valueMgPerLiter().toPlainString(),
196	                        req.testedAt());
197	                return new StoredResponse(202, toJson(new LateResponse(true, "DIACETYL_TEST", batchId)));
198	            }
199	            requireStatus(batch, BatchStatus.MAIN_FERMENT, "仅主酵期接受双乙酰检测");
200	            long id = readingRepository.insertDiacetyl(batchId, req.testedAt(),
201	                    req.valueMgPerLiter(), false);
202	            return new StoredResponse(201,
203	                    toJson(new DiacetylResponse(id, batchId, req.testedAt(),
204	                            req.valueMgPerLiter(), false)));
205	        });
206	    }
207	
208	    /**
209	     * 下达降温指令：双乙酰判定通过后，降温指令与曲线版本切换在同一事务内完成，
210	     * 降温按最新生效曲线版本执行，不得按旧曲线降温。
211	     */
212	    @Transactional
213	    public StoredResponse cooling(long batchId, CoolingRequest req) {
214	        String endpoint = "POST /api/batches/" + batchId + "/cooling";
215	        String fingerprint = idempotencyService.fingerprint(endpoint, req.requestId(),
216	                req.instructedAt().toString());
217	        return idempotent(req.requestId(), endpoint, fingerprint, () -> {
218	            FermentationBatch batch = mustFind(batchId);
219	            requireStatus(batch, BatchStatus.MAIN_FERMENT, "仅主酵期可下达降温指令");
220	            assertDiacetylPassed(batchId);
221	            int newVersion = curveRepository.findActiveVersion(batch.curveCode())
222	                    .orElseThrow(() -> ApiException.unprocessable(
223	                            "工艺曲线无生效版本: " + batch.curveCode()));
224	            batchRepository.applyCooling(batchId, newVersion, req.instructedAt());
225	            return new StoredResponse(200, toJson(toResponse(mustFind(batchId))));
226	        });
227	    }
228	
229	    /**
230	     * 开始后熟：COOLING → MATURATION。
231	     */
232	    @Transactional
233	    public StoredResponse startMaturation(long batchId, StartPhaseRequest req) {
234	        String endpoint = "POST /api/batches/" + batchId + "/maturation/start";
235	        String fingerprint = idempotencyService.fingerprint(endpoint, req.requestId(),
236	                req.startedAt().toString());
237	        return idempotent(req.requestId(), endpoint, fingerprint, () -> {
238	            FermentationBatch batch = mustFind(batchId);
239	            requireStatus(batch, BatchStatus.COOLING, "仅降温结束批次可开始后熟");
240	            batchRepository.startMaturation(batchId, req.startedAt());
241	            return new StoredResponse(200, toJson(toResponse(mustFind(batchId))));
242	        });
243	    }
244	
245	    /**
246	     * 延长后熟：仅允许一次，延长后要求后熟总时长 14 天。
247	     */
248	    @Transactional
249	    public StoredResponse extendMaturation(long batchId, ExtendMaturationRequest req) {
250	        String endpoint = "POST /api/batches/" + batchId + "/maturation/extend";
251	        String fingerprint = idempotencyService.fingerprint(endpoint, req.requestId(),
252	                req.extendedAt().toString());
253	        return idempotent(req.requestId(), endpoint, fingerprint, () -> {
254	            FermentationBatch batch = mustFind(batchId);
255	            requireStatus(batch, BatchStatus.MATURATION, "仅后熟期可延长后熟");
256	            if (batch.maturationExtended()) {
257	                throw ApiException.conflict("后熟仅允许延长一次，本批次已延长过");
258	            }
259	            batchRepository.markMaturationExtended(batchId);
260	            return new StoredResponse(200, toJson(toResponse(mustFind(batchId))));
261	        });
262	    }
263	
264	    /**
265	     * 成熟度判定：后熟保持不少于 7 天（恰 7 天合法，延长后 14 天）。
266	     * 不合格且未延长时可延长一次；延长后仍不合格整批复审（REVIEW 终态）。
267	     */
268	    @Transactional
269	    public StoredResponse judge(long batchId, JudgeRequest req) {
270	        String endpoint = "POST /api/batches/" + batchId + "/judge";
271	        String fingerprint = idempotencyService.fingerprint(endpoint, req.requestId(),
272	                req.judgedAt().toString());
273	        return idempotent(req.requestId(), endpoint, fingerprint, () -> {
274	            FermentationBatch batch = mustFind(batchId);
275	            requireStatus(batch, BatchStatus.MATURATION, "仅后熟期可判定成熟度");
276	            int requiredDays = batch.maturationExtended()
277	                    ? MATURATION_EXTENDED_DAYS : MATURATION_MIN_DAYS;
278	            boolean qualified = !req.judgedAt()
279	                    .isBefore(batch.maturationStartedAt().plusDays(requiredDays));
280	            BatchStatus newStatus;
281	            boolean canExtend;
282	            if (qualified) {
283	                newStatus = BatchStatus.JUDGED;
284	                canExtend = false;
285	            } else if (!batch.maturationExtended()) {
286	                newStatus = BatchStatus.MATURATION;
287	                canExtend = true;
288	            } else {
289	                newStatus = BatchStatus.REVIEW;
290	                canExtend = false;
291	            }
292	            batchRepository.updateJudgement(batchId, newStatus, req.judgedAt());
293	            return new StoredResponse(200, toJson(new JudgeResponse(
294	                    qualified, canExtend, newStatus, requiredDays, req.judgedAt())));
295	        });
296	    }
297	
298	    /**
299	     * 清酒转出：JUDGED → TRANSFERRED（终态）。重复转出返回幂等成功。
300	     */
301	    @Transactional
302	    public StoredResponse transfer(long batchId, TransferRequest req) {
303	        String endpoint = "POST /api/batches/" + batchId + "/transfer";
304	        String fingerprint = idempotencyService.fingerprint(endpoint, req.requestId(),
305	                req.transferredAt().toString());
306	        return idempotent(req.requestId(), endpoint, fingerprint, () -> {
307	            FermentationBatch batch = mustFind(batchId);
308	            if (batch.status() == BatchStatus.TRANSFERRED) {
309	                // 终态幂等：重复转出返回成功，不产生新的状态变更
310	                return new StoredResponse(200, toJson(toResponse(batch)));
311	            }
312	            requireStatus(batch, BatchStatus.JUDGED, "仅判定合格批次可清酒转出");
313	            batchRepository.completeTransfer(batchId, req.transferredAt());
314	            return new StoredResponse(200, toJson(toResponse(mustFind(batchId))));
315	        });
316	    }
317	
318	    /**
319	     * 查询批次详情（含判定口径复算所需的全部状态字段）。
320	     */
321	    @Transactional(readOnly = true)
322	    public BatchResponse getBatch(long batchId) {
323	        return toResponse(mustFind(batchId));
324	    }
325	
326	    /**
327	     * 查询批次某阶段温度采样链（按采样时间升序，可复算告警）。
328	     */
329	    @Transactional(readOnly = true)
330	    public List<ReadingResponse> getReadings(long batchId, CurvePhase phase) {
331	        mustFind(batchId);
332	        return readingRepository.findReadings(batchId, phase).stream()
333	                .map(r -> new ReadingResponse(r.id(), r.batchId(), r.phase(), r.curveVersion(),
334	                        r.sampledAt(), r.temperature(), r.setpoint(), r.deviation(),
335	                        r.outOfTolerance(), r.consecutiveOut(), r.alarmTriggered(), r.late()))
336	                .toList();
337	    }
338	
339	    /**
340	     * 查询批次双乙酰检测链（按检测时间升序，可复算降温资格）。
341	     */
342	    @Transactional(readOnly = true)
343	    public List<DiacetylResponse> getDiacetylTests(long batchId) {
344	        mustFind(batchId);
345	        return readingRepository.findDiacetylTests(batchId).stream()
346	                .map(t -> new DiacetylResponse(t.id(), t.batchId(), t.testedAt(),
347	                        t.valueMgPerLiter(), t.late()))
348	                .toList();
349	    }
350	
351	    private StoredResponse idempotent(String requestId, String endpoint, String fingerprint,
352	                                      Supplier<StoredResponse> action) {
353	        try {
354	            return idempotencyService.execute(requestId, endpoint, fingerprint, action);
355	        } catch (ConcurrentReplayException e) {
356	            // 并发同键：回滚本次业务写入，按首次受理结果裁决
357	            TransactionAspectSupport.currentTransactionStatus().setRollbackOnly();
358	            return idempotencyService.resolveConcurrent(e.requestId(), e.fingerprint());
359	        }
360	    }
361	
362	    private FermentationBatch mustFind(long batchId) {
363	        return batchRepository.findById(batchId)
364	                .orElseThrow(() -> ApiException.notFound("批次不存在: " + batchId));
365	    }
366	
367	    private void requireStatus(FermentationBatch batch, BatchStatus expected, String message) {
368	        if (batch.status() != expected) {
369	            throw ApiException.unprocessable(
370	                    message + "（当前状态 " + batch.status() + "，要求 " + expected + "）");
371	        }
372	    }
373	
374	    private LocalDateTime phaseStart(FermentationBatch batch, CurvePhase phase) {
375	        return switch (phase) {
376	            case MAIN_FERMENT -> batch.mainFermentStartedAt();
377	            case COOLING -> batch.coolingStartedAt();
378	            case MATURATION -> batch.maturationStartedAt();
379	        };
380	    }
381	
382	    /**
383	     * 双乙酰判定：检测链最后两次均不超过 0.10mg/L（恰 0.10 合格），
384	     * 且两次采样间隔不少于 12 小时（恰 12 小时合法）。
385	     */
386	    private void assertDiacetylPassed(long batchId) {
387	        List<DiacetylTest> tests = readingRepository.findDiacetylTests(batchId);
388	        if (tests.size() < 2) {
389	            throw ApiException.unprocessable("双乙酰检测不足两次，不允许降温");
390	        }
391	        DiacetylTest previous = tests.get(tests.size() - 2);
392	        DiacetylTest latest = tests.get(tests.size() - 1);
393	        if (previous.valueMgPerLiter().compareTo(DIACETYL_LIMIT) > 0
394	                || latest.valueMgPerLiter().compareTo(DIACETYL_LIMIT) > 0) {
