17	/**
18	 * 发酵批次数据访问。所有 SQL 参数化；并发入罐由 uk_batch_active_tank 唯一约束兜底。
19	 */
20	@Repository
21	public class BatchRepository {
22	
23	    private static final RowMapper<FermentationBatch> MAPPER = (rs, rowNum) -> new FermentationBatch(
24	            rs.getLong("id"),
25	            rs.getString("batch_no"),
26	            rs.getLong("tank_id"),
27	            rs.getString("curve_code"),
28	            rs.getInt("curve_version"),
29	            BatchStatus.valueOf(rs.getString("status")),
30	            toLdt(rs.getTimestamp("filled_at")),
31	            toLdt(rs.getTimestamp("main_ferment_started_at")),
32	            toLdt(rs.getTimestamp("cooling_started_at")),
33	            toLdt(rs.getTimestamp("maturation_started_at")),
34	            rs.getInt("maturation_extended") != 0,
35	            toLdt(rs.getTimestamp("judged_at")),
36	            toLdt(rs.getTimestamp("transferred_at")));
37	
38	    private final JdbcTemplate jdbc;
39	
40	    public BatchRepository(JdbcTemplate jdbc) {
41	        this.jdbc = jdbc;
42	    }
43	
44	    private static LocalDateTime toLdt(Timestamp ts) {
45	        return ts == null ? null : ts.toLocalDateTime();
46	    }
47	
48	    /**
49	     * 按罐编号查罐 ID，不存在返回空。
50	     */
51	    public Optional<Long> findTankIdByCode(String tankCode) {
52	        return jdbc.query("SELECT id FROM fermentation_tank WHERE tank_code = ?",
53	                rs -> rs.next() ? Optional.of(rs.getLong(1)) : Optional.empty(), tankCode);
54	    }
55	
56	    /**
57	     * 创建批次（满罐），active_tank_key 占用发酵罐；同罐并发由唯一约束拒绝。
58	     *
59	     * @return 生成的批次 ID
60	     */
61	    public long insert(String batchNo, long tankId, String curveCode, int curveVersion,
62	                       LocalDateTime filledAt, String activeTankKey) {
63	        KeyHolder keyHolder = new GeneratedKeyHolder();
64	        jdbc.update(con -> {
65	            PreparedStatement ps = con.prepareStatement(
66	                    "INSERT INTO fermentation_batch (batch_no, tank_id, curve_code, curve_version, status,"
67	                            + " filled_at, maturation_extended, active_tank_key)"
68	                            + " VALUES (?, ?, ?, ?, ?, ?, 0, ?)",
69	                    Statement.RETURN_GENERATED_KEYS);
70	            ps.setString(1, batchNo);
71	            ps.setLong(2, tankId);
72	            ps.setString(3, curveCode);
