33	@SpringBootTest
34	@AutoConfigureMockMvc
35	public abstract class BaseFermentationTest {
36	
37	    /** 合成基准时间：满罐时刻。 */
38	    static final LocalDateTime T0 = LocalDateTime.of(2026, 9, 26, 8, 0);
39	
40	    @Autowired
41	    MockMvc mockMvc;
