51	        jdbc.update("DELETE FROM late_event");
52	        jdbc.update("DELETE FROM temperature_reading");
53	        jdbc.update("DELETE FROM diacetyl_test");
54	        jdbc.update("DELETE FROM idempotency_record");
55	        jdbc.update("DELETE FROM fermentation_batch");
56	        jdbc.update("DELETE FROM curve_segment WHERE curve_id IN"
57	                + " (SELECT id FROM process_curve WHERE version > 1)");
58	        jdbc.update("DELETE FROM process_curve WHERE version > 1");
59	        jdbc.update("UPDATE process_curve SET status = 'ACTIVE'"
60	                + " WHERE curve_code = 'LAGER-CURVE' AND version = 1");
61	    }
62	
63	    MvcResult doPost(String url, Object body) throws Exception {
64	        return mockMvc.perform(post(url)
65	                        .contentType(MediaType.APPLICATION_JSON)
66	                        .content(objectMapper.writeValueAsString(body)))
67	                .andReturn();
68	    }
69	
70	    JsonNode json(MvcResult result) throws Exception {
71	        return objectMapper.readTree(result.getResponse().getContentAsString());
72	    }
73	
74	    String newRequestId() {
75	        return "req-" + UUID.randomUUID();
76	    }
77	
78	    /** 创建批次（满罐），断言 201 并返回批次 ID。 */
79	    long createBatch(String requestId, String batchNo, String tankCode) throws Exception {
80	        MvcResult result = doPost("/api/batches",
81	                new CreateBatchRequest(requestId, batchNo, tankCode, "LAGER-CURVE", T0));
82	        assertEquals(201, result.getResponse().getStatus(), "创建批次应返回 201");
83	        return json(result).get("id").asLong();
84	    }
85	
86	    void startMainFerment(long batchId, String requestId, LocalDateTime at) throws Exception {
87	        MvcResult result = doPost("/api/batches/" + batchId + "/main-ferment/start",
88	                new StartPhaseRequest(requestId, at));
89	        assertEquals(200, result.getResponse().getStatus(), "开始主酵应返回 200");
90	    }
