92	    MvcResult addReading(long batchId, String requestId, LocalDateTime at, String temperature)
93	            throws Exception {
94	        return doPost("/api/batches/" + batchId + "/temperature-readings",
95	                new TemperatureReadingRequest(requestId, at, new BigDecimal(temperature)));
96	    }
97	
98	    MvcResult addDiacetyl(long batchId, String requestId, LocalDateTime at, String value)
99	            throws Exception {
100	        return doPost("/api/batches/" + batchId + "/diacetyl-tests",
101	                new DiacetylTestRequest(requestId, at, new BigDecimal(value)));
102	    }
103	
104	    MvcResult cooling(long batchId, String requestId, LocalDateTime at) throws Exception {
105	        return doPost("/api/batches/" + batchId + "/cooling", new CoolingRequest(requestId, at));
106	    }
107	
108	    MvcResult startMaturation(long batchId, String requestId, LocalDateTime at) throws Exception {
109	        return doPost("/api/batches/" + batchId + "/maturation/start",
110	                new StartPhaseRequest(requestId, at));
111	    }
