118	    MvcResult judge(long batchId, String requestId, LocalDateTime at) throws Exception {
119	        return doPost("/api/batches/" + batchId + "/judge", new JudgeRequest(requestId, at));
120	    }
121	
122	    MvcResult transfer(long batchId, String requestId, LocalDateTime at) throws Exception {
123	        return doPost("/api/batches/" + batchId + "/transfer", new TransferRequest(requestId, at));
124	    }
125	
126	    /**
127	     * 驱动批次进入后熟：满罐 → 主酵 → 两次合格双乙酰（间隔 13h）→ 降温 → 后熟开始。
128	     *
129	     * @return 批次 ID；后熟开始时间为 {@code T0 + 15h}
130	     */
131	    long driveToMaturation(String batchNo, String tankCode) throws Exception {
132	        long id = createBatch(newRequestId(), batchNo, tankCode);
133	        startMainFerment(id, newRequestId(), T0);
134	        assertEquals(201, addDiacetyl(id, newRequestId(), T0.plusHours(1), "0.09")
135	                .getResponse().getStatus());
136	        assertEquals(201, addDiacetyl(id, newRequestId(), T0.plusHours(14), "0.08")
137	                .getResponse().getStatus());
138	        assertEquals(200, cooling(id, newRequestId(), T0.plusHours(14))
139	                .getResponse().getStatus());
140	        assertEquals(200, startMaturation(id, newRequestId(), T0.plusHours(15))
141	                .getResponse().getStatus());
142	        return id;
143	    }
