16	
17	    @Test
18	    @DisplayName("同键同参重放返回首次结果，不产生重复数据")
19	    void sameKeySameParamsReplaysFirstResult() throws Exception {
20	        String requestId = newRequestId();
21	        CreateBatchRequest request = new CreateBatchRequest(requestId, "B-IDEM-1", "TANK-1",
22	                "LAGER-CURVE", T0);
23	
24	        MvcResult first = doPost("/api/batches", request);
25	        assertEquals(201, first.getResponse().getStatus());
26	        MvcResult replay = doPost("/api/batches", request);
27	        assertEquals(201, replay.getResponse().getStatus(), "同键同参应重放首次状态码");
28	        assertEquals(first.getResponse().getContentAsString(),
29	                replay.getResponse().getContentAsString(), "同键同参应原样返回首次响应体");
30	
31	        Integer batchCount = jdbc.queryForObject(
32	                "SELECT COUNT(*) FROM fermentation_batch WHERE batch_no = 'B-IDEM-1'", Integer.class);
33	        assertEquals(1, batchCount, "重放不得产生重复批次");
34	
35	        // 采样重放：同键同参返回首次采样记录，不重复落库
36	        long id = json(first).get("id").asLong();
37	        startMainFerment(id, newRequestId(), T0);
38	        String readingRequestId = newRequestId();
39	        MvcResult r1 = addReading(id, readingRequestId, T0.plusHours(1), "10.50");
40	        MvcResult r2 = addReading(id, readingRequestId, T0.plusHours(1), "10.50");
41	        assertEquals(201, r2.getResponse().getStatus());
42	        assertEquals(json(r1).get("id").asLong(), json(r2).get("id").asLong(),
43	                "重放应返回首次采样记录 ID");
44	        Integer readingCount = jdbc.queryForObject(
45	                "SELECT COUNT(*) FROM temperature_reading WHERE batch_id = ?", Integer.class, id);
46	        assertEquals(1, readingCount, "重放不得产生重复采样");
47	    }
48	
49	    @Test
50	    @DisplayName("同键异参返回 409 且不改变业务状态与曲线版本")
51	    void sameKeyDifferentParamsReturns409() throws Exception {
52	        String requestId = newRequestId();
53	        MvcResult first = doPost("/api/batches",
54	                new CreateBatchRequest(requestId, "B-IDEM-2", "TANK-1", "LAGER-CURVE", T0));
55	        assertEquals(201, first.getResponse().getStatus());
56	
57	        // 同 requestId 携带不同罐号：409
58	        MvcResult conflict = doPost("/api/batches",
